#![no_std]

extern crate mm;

use core::ptr::NonNull;

// Include FFI bindings generated by bindgen via Meson
include!("bindings.rs");

// net_if helper functions for safe Rust wrappers around C FFI
// Provides safe abstractions over raw pointers

/// Safe wrapper around netif_tx_packet
///
/// # Arguments
/// * `nif` - Network interface (reference)
/// * `pkt` - Packet to transmit (reference to packet_t)
///
/// # Returns
/// 0 on success, negative value on failure
pub fn tx_packet(nif: &net_if, pkt: &packet_t) -> i32 {
    unsafe {
        netif_tx_packet(
            nif as *const net_if as *mut net_if,     // &net_if → *mut net_if
            pkt as *const packet_t as *mut packet_t, // &packet_t → *mut packet_t
        )
    }
}

/// Initialize packet offset fields based on network interface configuration
///
/// # Arguments
/// * `nif` - Network interface (reference)
/// * `pkt` - Packet to initialize (mutable reference to packet_t)
///
/// # Returns
/// 0 on success, negative value on failure
pub fn init_packet_offset(nif: &net_if, pkt: &mut packet_t) -> i32 {
    unsafe { netif_init_packet_offset(nif as *const net_if as *mut net_if, pkt as *mut packet_t) }
}

/// Get the transport layer offset for a network interface
///
/// # Arguments
/// * `nif` - Network interface (reference)
///
/// # Returns
/// Transport layer offset in bytes
pub fn transport_offset(nif: &net_if) -> u16 {
    unsafe { netif_trasport_offset(nif as *const net_if as *mut net_if) }
}

